local M = class("SimulateSpecialEventView",LikeOO.OOPopBase)
-- 侠客人生模拟器--事件
M.m_uiName = "SimulateLift/SimulateSpecialEvent"  -- prefab name
M.m_size_type = 2
M.m_iphoneXAdapter = true

function M:onEnter()
    self:bindUI()
    self:refreshUI()
end

function M:refreshUI()
    self:setTextByLanKey("text_content", self.m_model.m_title )
    local contents = self.m_model.m_eventContents
    local contentCount = table.nums(contents)
    for index = 1, 4 do
        local isShow = index <= contentCount 
        self:setObjectVisible("btn_selectBtn_"..index, isShow)
        if isShow then
            self:setTextByLanKey("text_selectText_"..index, Language:getTextByKey(contents[index]) )
        end
    end
end

function M:bindUI()
    self:setTextByLanKey("text_title", "simulateLeft_text_0028")
end

function M:destroy()
    M.super.destroy(self)
end

return M
